package com.billbookmanagement.modules.products.repository;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;import java.util.*;
@Repository public class ProductRepository{private final JdbcTemplate db;public ProductRepository(JdbcTemplate db){this.db=db;}public List<Map<String,Object>> list(long b){return db.queryForList("SELECT * FROM product WHERE business_id=? ORDER BY name",b);}public Map<String,Object> one(long b,long id){List<Map<String,Object>> x=db.queryForList("SELECT * FROM product WHERE id=? AND business_id=?",id,b);return x.isEmpty()?null:x.getFirst();}public Map<String,Object> active(long b,long id){List<Map<String,Object>> x=db.queryForList("SELECT * FROM product WHERE id=? AND business_id=? AND is_active=TRUE",id,b);return x.isEmpty()?null:x.getFirst();}public void create(long b,Object...v){db.update("INSERT INTO product(business_id,product_code,name,description,unit_of_measure,current_unit_price,default_tax_rate,is_active) VALUES(?,?,?,?,?,?,?,?)",b,v);}public long id(){return db.queryForObject("SELECT LAST_INSERT_ID()",Long.class);}public int update(long b,long id,Object...v){return db.update("UPDATE product SET product_code=?,name=?,description=?,unit_of_measure=?,current_unit_price=?,default_tax_rate=?,is_active=? WHERE id=? AND business_id=?",v[0],v[1],v[2],v[3],v[4],v[5],v[6],id,b);}}
